import { tags } from "typia";

/**
 * Individual search query analytics with performance and engagement metrics.
 *
 * Represents detailed analytics for a specific search query including
 * frequency, result counts, click patterns, and user interaction data. This
 * data helps understand which search terms are most valuable to the community
 * and how effectively the search system responds to user queries.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IEconomicDiscussionSearchQueryAnalytics = {
  /** The actual search query text entered by users. */
  query_text: string;

  /** Number of times this query has been executed across all users. */
  frequency: number & tags.Type<"int32">;

  /** Average number of search results returned for this query. */
  results_count: number & tags.Type<"int32">;

  /** Percentage of searches that resulted in a result click (0.0 to 1.0). */
  click_through_rate?: number | undefined;

  /** Average position of clicked results, indicating search result quality. */
  average_click_position?: number | undefined;

  /** Most recent timestamp when this query was executed. */
  last_used_at?: (string & tags.Format<"date-time">) | undefined;

  /**
   * Economic discussion categories most commonly associated with this search
   * query.
   */
  category_associations?: string[] | undefined;
};
